//! Registry captures are replayable evidence, never a claim of a live fetch.
use super::{FetchError, SourceCapture, sha256_hex};
use crate::seed::parser::parse_lino;

pub(super) fn read_seed_capture(url: &str, raw: &str) -> Result<Option<SourceCapture>, FetchError> {
    let root = parse_lino(raw);
    let matches: Vec<_> = root.children.iter().filter(|node| node.name == "source-captures")
        .flat_map(|node| node.children.iter()).filter(|node| node.name == "capture" && node.find_child_value("url") == url).collect();
    let Some(node) = matches.first() else { return Ok(None); };
    if matches.len() != 1 { return Err(FetchError::Cache(String::from("ambiguous_capture"))); }
    let bytes = node.find_child_value("body").as_bytes().to_vec();
    let fetched_at = node.find_child_value("fetched-at");
    let recorded = node.find_child_value("sha256");
    let sha256 = sha256_hex(&bytes);
    if fetched_at.parse::<u64>().ok().filter(|time| *time > 0).is_none()
        || sha256 != recorded || node.id != recorded {
        return Err(FetchError::Cache(String::from("invalid_capture")));
    }
    Ok(Some(SourceCapture { source_url: url.to_owned(), fetched_at: fetched_at.to_owned(), sha256, cached: true, bytes }))
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn arbitrary_capture_is_verified_before_replay() {
        let body = "arbitrary captured bytes";
        let digest = sha256_hex(body.as_bytes());
        let raw = format!("source-captures\n  capture {digest}\n    url https://example.test/entry\n    fetched-at 1720000000\n    sha256 {digest}\n    body \"{body}\"\n");
        let capture = read_seed_capture("https://example.test/entry", &raw).unwrap().unwrap();
        assert_eq!(capture.bytes(), body.as_bytes());
        assert_eq!(capture.fetched_at(), "1720000000");
        assert!(capture.cached());
        assert!(read_seed_capture("https://example.test/other", &raw).unwrap().is_none());
        assert!(read_seed_capture("https://example.test/entry", &raw.replace(body, "tampered bytes")).is_err());
        assert!(read_seed_capture("https://example.test/entry", &raw.replace("1720000000", "0")).is_err());
    }
}
